-- =============================================================================
-- Відтворення повної фінальної схеми БД у новій порожній базі PostgreSQL.
-- Поєднує базову структуру (7 таблиць із модуля 1) та розширення міграції 001.
-- Не виконує DROP TABLE і безпечний при повторному запуску завдяки IF NOT EXISTS.
-- =============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS "users" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(255) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "first_name" varchar(255) NOT NULL,
  "last_name" varchar(255) NOT NULL,
  "middle_name" varchar(255),
  "is_admin" bool NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE IF NOT EXISTS "categories" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS "order_statuses" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) NOT NULL
);

CREATE TABLE IF NOT EXISTS "products" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_id" int NOT NULL,
  "name" varchar(255) NOT NULL,
  "description" text NOT NULL,
  "specifications" text NOT NULL DEFAULT '',
  "price" decimal(10,2) NOT NULL,
  "stock_quantity" int NOT NULL,
  "version" int NOT NULL DEFAULT 1,
  "is_active" boolean NOT NULL,
  "image_path" text NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE IF NOT EXISTS "cart_items" (
  "user_id" int NOT NULL,
  "product_id" int NOT NULL,
  "quantity" int NOT NULL,
  "updated_at" timestamp DEFAULT (now()),
  PRIMARY KEY ("user_id", "product_id")
);

CREATE TABLE IF NOT EXISTS "orders" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "order_number" varchar(50) UNIQUE NOT NULL,
  "status_id" int NOT NULL,
  "recipient_first_name" varchar(100) NOT NULL DEFAULT '',
  "recipient_last_name" varchar(100) NOT NULL DEFAULT '',
  "recipient_phone" varchar(30) NOT NULL DEFAULT '',
  "recipient_email" varchar(255) NOT NULL DEFAULT '',
  "comment" varchar(500),
  "delivery_method" varchar(50) NOT NULL DEFAULT 'Самовивіз',
  "pickup_location" varchar(255) NOT NULL DEFAULT '',
  "payment_method" varchar(50) NOT NULL DEFAULT 'Оплата при отриманні',
  "is_paid" boolean NOT NULL DEFAULT false,
  "paid_at" timestamp,
  "idempotency_key" varchar(100),
  "idempotency_payload_hash" varchar(128),
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE IF NOT EXISTS "order_items" (
  "order_id" int NOT NULL,
  "product_id" int NOT NULL,
  "product_name_snapshot" varchar(255) NOT NULL DEFAULT '',
  "price_at_purchase" decimal(10,2) NOT NULL,
  "quantity" int NOT NULL,
  PRIMARY KEY ("order_id", "product_id")
);

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'products_category_id_fkey') THEN
        ALTER TABLE "products" ADD CONSTRAINT "products_category_id_fkey"
            FOREIGN KEY ("category_id") REFERENCES "categories" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'cart_items_user_id_fkey') THEN
        ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_user_id_fkey"
            FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'cart_items_product_id_fkey') THEN
        ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_product_id_fkey"
            FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_user_id_fkey') THEN
        ALTER TABLE "orders" ADD CONSTRAINT "orders_user_id_fkey"
            FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_status_id_fkey') THEN
        ALTER TABLE "orders" ADD CONSTRAINT "orders_status_id_fkey"
            FOREIGN KEY ("status_id") REFERENCES "order_statuses" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'order_items_order_id_fkey') THEN
        ALTER TABLE "order_items" ADD CONSTRAINT "order_items_order_id_fkey"
            FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'order_items_product_id_fkey') THEN
        ALTER TABLE "order_items" ADD CONSTRAINT "order_items_product_id_fkey"
            FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;
    END IF;
END $$;

COMMIT;
